export type ParsedProposePoolInstruction<
  TProgram extends string = typeof SHORTWIN_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    config: TAccountMetas[0];
    /**
     * The venue-upgrade latch (A7; module docs step 3): a proposal is refused while the bit of
     * the candidate's program is set (`VenueUpgraded`, M4-SEC-8). Read only.
     */
    venueGuard: TAccountMetas[1];
    market: TAccountMetas[2];
    /** the handler); the candidate's token side must be this mint under that program. */
    mint: TAccountMetas[3];
    /**
     * The cached SOL/USD price: the tier the market would have on a window candidate, whose
     * opening caps its open positions must fit ("switch only if all fit"; module docs step 6).
     * Read only.
     */
    oracleCache: TAccountMetas[4];
    eventAuthority: TAccountMetas[5];
    program: TAccountMetas[6];
  };
  data: ProposePoolInstructionData;
};

export function parseProposePoolInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedProposePoolInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      venueGuard: getNextAccount(),
      market: getNextAccount(),
      mint: getNextAccount(),
      oracleCache: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getProposePoolInstructionDataDecoder().decode(instruction.data),
  };
}
